import{_ as e,o as t,c as r,a5 as s}from"./chunks/framework.CXroN2RO.js";const m=JSON.parse('{"title":"コンピュータの部品から読む","description":"","frontmatter":{"title":"コンピュータの部品から読む","study":{"source":"新規執筆","section":"learning","format":"path","status":"published","domain":"hardware","collection":"foundations","order":1,"summary":"CPU・RAM・SSDの役割を知り、命令の実行とデータの置き場所へ進む読み順。身近なゲームの起動から内部を調べる。"}},"headers":[],"relativePath":"guide/hardware-basics.md","filePath":"guide/hardware-basics.md"}'),i={name:"guide/hardware-basics.md"};function o(l,a,d,h,n,u){return t(),r("div",null,[...a[0]||(a[0]=[s('<h1 id="コンピュータの部品から読む" tabindex="-1">コンピュータの部品から読む <a class="header-anchor" href="#コンピュータの部品から読む" aria-label="Permalink to &quot;コンピュータの部品から読む&quot;">​</a></h1><p>CPU、メモリ、ストレージという名前を見かけても、それぞれが何を担当するか曖昧なときの入口です。まずゲームを起動する場面から部品の関係を見て、命令とデータの動きを追います。</p><h2 id="読む順番" tabindex="-1">読む順番 <a class="header-anchor" href="#読む順番" aria-label="Permalink to &quot;読む順番&quot;">​</a></h2><ol><li><a href="/study/hardware/computer-components.html">コンピュータを構成する部品</a>で、CPU、RAM、ストレージ、GPU、入出力の担当をつかみます。</li><li><a href="/study/hardware/cpu/instruction-execution.html">CPUが命令を実行する仕組み</a>で、命令、レジスタ、メモリの関係を追います。</li><li><a href="/study/hardware/memory/ram-cache-and-storage.html">RAM・キャッシュ・ストレージ</a>で、計算中のデータと保存したデータの置き場所を比べます。</li></ol><p>ビットやバイト、2進数の読み方を確認したいときは、<a href="/study/data/integer-bits-and-bytes.html">整数・ビット・バイト</a>を参照してください。</p><h2 id="確かめること" tabindex="-1">確かめること <a class="header-anchor" href="#確かめること" aria-label="Permalink to &quot;確かめること&quot;">​</a></h2><ul><li>ゲームの実行中に使うデータと、終了後も保存しておくデータを、それぞれどこに置くか説明できる。</li><li>CPUのレジスタとRAMがどう関わるか、命令の小さな例でたどれる。</li><li>メモリの容量と、読み書きの待ち時間が指すものを区別できる。</li></ul><h2 id="さらに内部を調べる" tabindex="-1">さらに内部を調べる <a class="header-anchor" href="#さらに内部を調べる" aria-label="Permalink to &quot;さらに内部を調べる&quot;">​</a></h2><p>起動時にOSがする準備は<a href="/study/os/process-startup.html">実行ファイルの起動</a>、アプリが扱うアドレスは<a href="/study/os/virtual-memory.html">仮想メモリ</a>へ進みます。描画を調べたい場合は<a href="/study/hardware/gpu/what-is-gpu.html">GPUとは何か</a>、部品同士の接続を調べたい場合は<a href="/study/hardware/io/pcie-links.html">PCI Express</a>が次の入口です。</p><p>通信の基礎は<a href="/study/guide/network-basics.html">ネットワークの基本から読む</a>へ進んでください。</p>',10)])])}const p=e(i,[["render",o]]);export{m as __pageData,p as default};
